db.exec(`
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT,description TEXT,price REAL NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,image TEXT,status TEXT DEFAULT 'Active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,customer_id INTEGER REFERENCES users(id),order_no TEXT UNIQUE NOT NULL,total REAL NOT NULL DEFAULT 0,status TEXT DEFAULT 'Pending Payment',payment_method TEXT,payment_status TEXT DEFAULT 'Pending',delivery_address TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id),name TEXT,price REAL,qty INTEGER);
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT,price_from REAL DEFAULT 0,icon TEXT,status TEXT DEFAULT 'Active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_requests(id INTEGER PRIMARY KEY,customer_id INTEGER REFERENCES users(id),service_id INTEGER REFERENCES services(id),name TEXT,phone TEXT,vehicle TEXT,preferred_date TEXT,notes TEXT,status TEXT DEFAULT 'New',amount REAL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT,phone TEXT,image TEXT,bio TEXT,status TEXT DEFAULT 'Active',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY,customer_id INTEGER REFERENCES users(id),subject TEXT,context_type TEXT,context_id TEXT,status TEXT DEFAULT 'Open',assigned_to TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_messages(id INTEGER PRIMARY KEY,conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_type TEXT NOT NULL,sender_id INTEGER,message TEXT NOT NULL,attachment TEXT,created_at TEXT NOT NULL,read_at TEXT);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),service_request_id INTEGER REFERENCES service_requests(id),reference TEXT UNIQUE,method TEXT,amount REAL,status TEXT DEFAULT 'Pending',provider TEXT DEFAULT 'Configured at hosting',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS legal_documents(id INTEGER PRIMARY KEY,title TEXT NOT NULL,category TEXT,filename TEXT,path TEXT NOT NULL,mime TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_links(id INTEGER PRIMARY KEY,request_type TEXT NOT NULL,request_id INTEGER NOT NULL,conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,created_at TEXT NOT NULL,UNIQUE(request_type,request_id));
CREATE TABLE IF NOT EXISTS admin_roles(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT,permissions TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
`);
