function token(req){let a=req.headers.authorization||'';return a.startsWith('Bearer ')?a.slice(7):''}function user(req){let t=token(req);if(!t)return null;return db.prepare('SELECT u.id,u.name,u.email,u.role FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires_at>?').get(t,now())||null}
function audit(u,action,entity,id,details=''){db.prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,details,created_at) VALUES(?,?,?,?,?,?)').run(u?.id||null,action,entity,String(id||''),details,now())}
function vehicleRows(where='1=1',params=[]){return db.prepare(`SELECT v.*, (SELECT path FROM media m WHERE m.vehicle_id=v.id AND m.type='image' AND m.category!='360' ORDER BY m.is_primary DESC,m.sort_order LIMIT 1) image, (SELECT count(*) FROM favourites f WHERE f.vehicle_id=v.id) saves, (SELECT count(*) FROM enquiries e WHERE e.vehicle_id=v.id) enquiries FROM vehicles v WHERE ${where} ORDER BY v.featured DESC,v.created_at DESC`).all(...params)}
function oauthFinish(res,provider,providerId,email,name){email=String(email||'').toLowerCase();let x=db.prepare('SELECT * FROM users WHERE email=?').get(email);if(!x){let r=db.prepare('INSERT INTO users(name,email,password_hash,role,created_at) VALUES(?,?,?,?,?)').run(name,email,hash(crypto.randomBytes(32).toString('hex')),'customer',now());x=db.prepare('SELECT * FROM users WHERE id=?').get(r.lastInsertRowid);db.prepare('INSERT OR IGNORE INTO customers(name,phone,email,created_at) VALUES(?,?,?,?)').run(name,'',email,now())}db.prepare('INSERT INTO oauth_accounts(user_id,provider,provider_id,created_at) VALUES(?,?,?,?) ON CONFLICT(provider,provider_id) DO UPDATE SET user_id=excluded.user_id').run(x.id,provider,providerId,now());let t=crypto.randomBytes(32).toString('hex'),exp=new Date(Date.now()+30*864e5).toISOString();db.prepare('INSERT INTO sessions(token,user_id,expires_at,created_at) VALUES(?,?,?,?)').run(t,x.id,exp,now());let payload=Buffer.from(JSON.stringify({token:t,user:{id:x.id,name:x.name,email:x.email,phone:'',role:'customer'}})).toString('base64url');res.writeHead(302,{location:'/?oauth='+payload+'#account'});res.end()}

function setting(k,def=''){let x=db.prepare('SELECT value FROM settings WHERE key=?').get(k);return x?.value||def}
function setSetting(k,v){db.prepare('INSERT INTO settings(key,value,updated_at) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').run(k,String(v||''),now())}
function normalizeWa(n){let x=String(n||'').replace(/\D/g,'');if(x.startsWith('0'))x='233'+x.slice(1);return x}
async function sendEmail(to,subject,body,html=''){let key=process.env.RESEND_API_KEY||setting('resend_api_key');if(!key||!to)return {skipped:true};let from=process.env.NOTIFY_FROM_EMAIL||setting('from_email','Revolt AutoLink <onboarding@resend.dev>');try{let payload={from,to:[to],subject,text:body};if(html)payload.html=html;let r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{authorization:'Bearer '+key,'content-type':'application/json'},body:JSON.stringify(payload)});return {ok:r.ok,status:r.status}}catch(e){return {ok:false,error:e.message}}}
async function sendWhatsApp(to,body){let token=process.env.WHATSAPP_TOKEN||setting('whatsapp_token'),pid=process.env.WHATSAPP_PHONE_NUMBER_ID||setting('whatsapp_phone_number_id'),n=normalizeWa(to);if(!token||!pid||!n)return {skipped:true};try{let r=await fetch(`https://graph.facebook.com/v23.0/${pid}/messages`,{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({messaging_product:'whatsapp',to:n,type:'text',text:{body}})});return {ok:r.ok}}catch(e){return {ok:false}}}
async function notifyRequest(user,kind,id,summary){let adminEmail=process.env.ADMIN_NOTIFY_EMAIL||setting('admin_notify_email'),adminWa=process.env.ADMIN_NOTIFY_WHATSAPP||setting('admin_notify_whatsapp','0500081646'),customerEmail=user?.email||'',c=db.prepare('SELECT phone FROM customers WHERE email=?').get(customerEmail),customerWa=c?.phone||'';let msg=`Revolt AutoLink: ${kind} #${id} received. ${summary||''}`.trim();Promise.allSettled([sendEmail(customerEmail,`Revolt AutoLink - ${kind} received`,msg),sendWhatsApp(customerWa,msg),sendEmail(adminEmail,`New Revolt AutoLink ${kind} #${id}`,msg),sendWhatsApp(adminWa,`ADMIN: ${msg}`)]).catch(()=>{})}
function inspectionApprovalTemplate(x){let date=x.approved_date||x.preferred_date||'',time=x.approved_time||x.preferred_time||'',title=x.vehicle_title||'your selected vehicle';let text=`Hello ${x.name}, thank you for choosing Revolt AutoLink. Your inspection for ${title} has been approved. Date: ${date}. Time: ${time}. We appreciate your request and look forward to assisting you. If you need to make a change, reply through your Revolt AutoLink chat or contact our team. Find It. Trust It. Drive It.`;let html=`<div style="font-family:Arial,sans-serif;background:#f5f6f8;padding:28px;color:#111827"><div style="max-width:620px;margin:auto;background:#fff;border-radius:16px;overflow:hidden;border:1px solid #e5e7eb"><div style="background:#111827;color:white;padding:24px 28px;border-bottom:4px solid #e11d2e"><div style="font-size:13px;color:#fb7185;font-weight:700;letter-spacing:.08em">REVOLT AUTOLINK</div><h2 style="margin:7px 0 0">Inspection Confirmed</h2></div><div style="padding:28px"><p>Hello <b>${x.name}</b>,</p><p>Thank you for choosing Revolt AutoLink. Your vehicle inspection has been approved and scheduled as follows:</p><div style="background:#f8fafc;border-left:4px solid #e11d2e;padding:18px;margin:22px 0;border-radius:8px"><div style="font-size:17px;font-weight:700;margin-bottom:10px">${title}</div><div>📅 Date: <b>${date}</b></div><div style="margin-top:8px">🕒 Time: <b>${time}</b></div></div><p>We appreciate your request and look forward to assisting you. Please arrive on time. If you need to make a change, reply through your Revolt AutoLink chat or contact our team.</p><p style="margin-top:26px">Thank you,<br><b>Revolt AutoLink Team</b></p><p style="margin-top:24px;color:#6b7280;font-size:13px"><b>Find It. Trust It. Drive It.</b></p></div></div></div>`;return {text,html,date,time,title}}
async function sendInspectionApproval(x){let t=inspectionApprovalTemplate(x),channel=String(x.contact_method||'Email').toLowerCase(),results={};if(channel.includes('email'))results.email=await sendEmail(x.customer_email||'',`Inspection Approved - ${t.title}`,t.text,t.html);if(channel.includes('whatsapp'))results.whatsapp=await sendWhatsApp(x.phone,t.text);return {channel:x.contact_method,results,...t}}
function requestConversation(user,kind,id,subject,initial){if(!user||user.role!=='customer')return null;let r=db.prepare('INSERT INTO conversations(customer_id,subject,context_type,context_id,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?)').run(user.id,subject,kind,String(id),'Open',now(),now());let cid=Number(r.lastInsertRowid);db.prepare('INSERT OR IGNORE INTO request_links(request_type,request_id,conversation_id,created_at) VALUES(?,?,?,?)').run(kind,id,cid,now());db.prepare('INSERT INTO chat_messages(conversation_id,sender_type,sender_id,message,created_at) VALUES(?,?,?,?,?)').run(cid,'system',null,initial,now());return cid}
