if(p==='/api/orders'&&method==='POST'){if(!u||u.role!=='customer')return json(res,401,{error:'Please sign in to checkout'});let b=await parseBody(req),items=Array.isArray(b.items)?b.items:[];if(!items.length)return json(res,400,{error:'Cart is empty'});let total=0,valid=[];for(const it of items){let pr=db.prepare("SELECT * FROM products WHERE id=? AND status='Active'").get(+it.id);if(!pr||pr.stock<1)continue;let qty=Math.max(1,Math.min(+it.qty||1,pr.stock));total+=pr.price*qty;valid.push([pr,qty])}if(!valid.length)return json(res,400,{error:'No available items in cart'});let no='RAL-'+Date.now(),r=db.prepare('INSERT INTO orders(customer_id,order_no,total,status,payment_method,payment_status,delivery_address,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)').run(u.id,no,total,'Pending Payment',b.payment_method||'Mobile Money','Pending',b.delivery_address||'',now(),now());for(const [pr,qty] of valid)db.prepare('INSERT INTO order_items(order_id,product_id,name,price,qty) VALUES(?,?,?,?,?)').run(r.lastInsertRowid,pr.id,pr.name,pr.price,qty);let ref='RALPAY'+Date.now(),secret=process.env.PAYSTACK_SECRET_KEY||setting('paystack_secret_key'),provider=setting('payment_provider','Paystack'),authUrl='';db.prepare('INSERT INTO payments(order_id,reference,method,amount,status,provider,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(r.lastInsertRowid,ref,b.payment_method||'Mobile Money',total,'Pending',provider,now(),now());if(secret&&provider==='Paystack'){try{let cb=setting('payment_callback_url',process.env.APP_URL?process.env.APP_URL+'/#account':'');let channels=b.payment_method==='Card'?['card']:['mobile_money'];let pr=await fetch('https://api.paystack.co/transaction/initialize',{method:'POST',headers:{authorization:'Bearer '+secret,'content-type':'application/json'},body:JSON.stringify({email:u.email,amount:String(Math.round(total*100)),currency:setting('payment_currency','GHS'),reference:ref,channels,callback_url:cb,metadata:JSON.stringify({order_id:Number(r.lastInsertRowid),order_no:no})})});let pd=await pr.json();if(pr.ok&&pd.status)authUrl=pd.data.authorization_url||''}catch(e){console.error('Paystack initialize failed',e.message)}}return json(res,201,{id:Number(r.lastInsertRowid),order_no:no,total,payment_reference:ref,payment_status:'Pending',authorization_url:authUrl,message:authUrl?'Continue to secure payment.':'Order created. Configure Paystack in Admin > Payment Setup to collect live payments.'})}
if(p==='/api/orders'&&method==='GET'){if(u.role!=='customer')return json(res,200,db.prepare('SELECT * FROM orders ORDER BY created_at DESC').all());return json(res,200,db.prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY created_at DESC').all(u.id))}
if(p==='/api/service-requests'&&method==='POST'){if(!u||u.role!=='customer')return json(res,401,{error:'Please sign in to request a service'});let b=await parseBody(req),r=db.prepare('INSERT INTO service_requests(customer_id,service_id,name,phone,vehicle,preferred_date,notes,status,amount,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(u.id,+b.service_id||null,b.name||u.name,b.phone||'',b.vehicle||'',b.preferred_date||'',b.notes||'','New',0,now(),now()),id=Number(r.lastInsertRowid),svc=db.prepare('SELECT name FROM services WHERE id=?').get(+b.service_id),cid=requestConversation(u,'service_request',id,`${svc?.name||'Service'} request #${id}`,'Your service request has been received. Reply here to speak directly with the Revolt team.');notifyRequest(u,'service request',id,`${svc?.name||''} ${b.vehicle||''}`);return json(res,201,{id,conversation_id:cid})}
