if(p==='/api/chat/conversations'&&method==='GET'){if(!u)return json(res,401,{error:'Please sign in to chat'});if(u.role!=='customer')return json(res,200,db.prepare('SELECT c.*,u.name customer_name,u.email customer_email,(SELECT message FROM chat_messages m WHERE m.conversation_id=c.id ORDER BY id DESC LIMIT 1) last_message FROM conversations c LEFT JOIN users u ON u.id=c.customer_id ORDER BY c.updated_at DESC').all());return json(res,200,db.prepare('SELECT * FROM conversations WHERE customer_id=? ORDER BY updated_at DESC').all(u.id))}
let cm=p.match(/^\/api\/chat\/conversations\/(\d+)\/messages$/);if(cm&&method==='GET'){if(!u)return json(res,401,{error:'Sign in required'});let c=db.prepare('SELECT * FROM conversations WHERE id=?').get(+cm[1]);if(!c||!(u.role!=='customer'||c.customer_id===u.id))return json(res,403,{error:'Forbidden'});return json(res,200,db.prepare('SELECT * FROM chat_messages WHERE conversation_id=? ORDER BY id').all(c.id))}
if(cm&&method==='POST'){let c=db.prepare('SELECT * FROM conversations WHERE id=?').get(+cm[1]);if(!c||!(u.role!=='customer'||c.customer_id===u.id))return json(res,403,{error:'Forbidden'});let b=await parseBody(req);if(!String(b.message||'').trim())return json(res,400,{error:'Message required'});let sender=u.role!=='customer'?'admin':'customer';let r=db.prepare('INSERT INTO chat_messages(conversation_id,sender_type,sender_id,message,created_at) VALUES(?,?,?,?,?)').run(c.id,sender,u.id,String(b.message).trim(),now());db.prepare('UPDATE conversations SET updated_at=? WHERE id=?').run(now(),c.id);return json(res,201,{id:Number(r.lastInsertRowid)})}

