const types={'.html':'text/html; charset=utf-8','.css':'text/css','.js':'application/javascript','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.svg':'image/svg+xml','.ico':'image/x-icon','.webp':'image/webp','.mp4':'video/mp4','.webm':'video/webm','.mp3':'audio/mpeg','.wav':'audio/wav','.ogg':'audio/ogg'};

function refreshSmartAlertMatches(vehicleId){
 try{let v=db.prepare('SELECT * FROM vehicles WHERE id=?').get(vehicleId);if(!v||String(v.status).toLowerCase()!=='available')return;for(const a of db.prepare("SELECT * FROM alerts WHERE status='Active'").all()){let c={};try{c=JSON.parse(a.criteria||'{}')}catch{};let ok=true;if(c.make)ok=ok&&String(v.make||'').toLowerCase().includes(String(c.make).toLowerCase());if(c.model)ok=ok&&String(v.model||'').toLowerCase().includes(String(c.model).toLowerCase());if(+c.budget>0)ok=ok&&+v.price<=+c.budget;if(c.location)ok=ok&&String(v.location||'').toLowerCase().includes(String(c.location).toLowerCase());if(ok&&a.last_match_vehicle_id!==v.id)db.prepare('UPDATE alerts SET match_count=coalesce(match_count,0)+1,last_match_vehicle_id=? WHERE id=?').run(v.id,a.id)}
 }catch(e){console.error('Smart alert match failed',e.message)}
}
const server=http.createServer(async(req,res)=>{try{let u=user(req);if(req.url.startsWith('/api/'))return await api(req,res,u);let pathname=decodeURIComponent(new URL(req.url,'http://x').pathname);if(pathname.startsWith('/uploads/')){let uf=path.join(UPLOADS,path.basename(pathname));if(fs.existsSync(uf)){res.writeHead(200,{'content-type':types[path.extname(uf)]||'application/octet-stream','cache-control':'public, max-age=86400'});return fs.createReadStream(uf).pipe(res)}}let f=path.join(PUBLIC,pathname==='/'?'index.html':pathname);if(!f.startsWith(PUBLIC))return json(res,403,{error:'Forbidden'});if(!fs.existsSync(f)||fs.statSync(f).isDirectory())f=path.join(PUBLIC,'index.html');res.writeHead(200,{'content-type':types[path.extname(f)]||'application/octet-stream','cache-control':'no-cache'});fs.createReadStream(f).pipe(res)}catch(e){console.error(e);json(res,500,{error:'Server error'})}});
server.listen(process.env.PORT||3000,()=>console.log('Revolt AutoLink running on http://localhost:'+(process.env.PORT||3000)));
